DELETE FROM inspection_item_revisions WHERE item_id = '7.8.1' AND introduction_type != 'revision';
INSERT INTO inspection_item_revisions (item_id, effective_date, expiry_date, introduction_type, description) VALUES ('7.8.1', '2022-03-02', NULL, 'current', '7.8.1 추락 위험에 대한 보호
엘리베이터의 정상 운행 중, 카가 문의 잠금해제구간에 정지하고 있지 않거나 정지 시점이 아닌 경우 승강장문(또는 여러 문짝이 있는 경우 어떤 문짝이라도)의 개방은 가능하지 않아야 한다.
잠금해제구간은 승강장 바닥의 위․아래로 각각 0.2 m를 초과하여 연장되지 않아야 한다. 다만, 기계적으로 작동되는 승강장문과 카문이 동시에 작동되는 경우에는 잠금해제구간을 승강장 바닥의 위․아래로 각각 0.35 m까지 연장할 수 있다.');
INSERT INTO inspection_item_revisions (item_id, effective_date, expiry_date, introduction_type, description) VALUES ('7.8.1', '2013-09-15', '2022-03-01', 'old', '7.7.1 추락 위험에 대한 보호
엘리베이터가 정상적으로 운행하는 중에 카가 문의 잠금해제구간에서 정지하고 있지 않거나 정지 시점이 아닌 경우에는 승강장문(또는 여러 문짝이 있는 경우 어떤 문짝이라도)의 개방은 가능하지 않아야 한다.
잠금해제구간은 승강장 바닥의 위·아래로 0.2 m 이하이어야 한다. 다만, 기계적으로 작동되는 카문과 승강장문이 동시에 작동되는 경우의 잠금해제구간은 승강장 바닥의 위·아래로 최대 0.35 m 까지 연장될 수 있다.');
INSERT INTO inspection_item_revisions (item_id, effective_date, expiry_date, introduction_type, description) VALUES ('7.8.1', '2008-11-07', '2013-09-14', 'old', '3.1.6(2) 카가 정지하고 있지 않은 층에서는 특수한 키를 사용하지 않으면 밖에서 승강로의 출입문을 열 수 없도록 하는 장치를 설치하여야 하며, 승강장 출입문을 개방하기 위한 장치는 그림 3에 규정된 삼각형의 잠금해제장치의 규격에 적합하여야 한다. 또한, 특수한 키에는 사용상의 위험과 승강장문이 닫힌 후 문의 잠금여부를 확인해야 하는 등의 주의사항이 표시되어야 한다.

4.1.5(2) 엘리베이터를 사용하는 모든 승강장에는 비상해제장치를 설치하여야 하고, 카가 정지하고 있지 않은 층에서는 특수한 키를 사용하지 않으면 문을 열 수 없어야 한다.');
